(function(){'use strict';
/* Fact Conflict and Contradiction Resolution Database generator — jahdb-fact-conflict-contradiction-resolution-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   Type: Fact-checked public information. */
function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var PREFIX='JAH-FCCR-';
var DBTITLE='Fact Conflict and Contradiction Resolution Database';
var DESC='Conflicting records, source reliability assessment, time-dependent facts, and reconciliation procedures — how to resolve contradictions and decide what is true when sources disagree.';
var CATS=["conflict-types", "provenance-assessment", "reconciliation", "temporal-truth", "consensus-methods", "resolution-procedures"];
var SRC='public-harvest';
var SRC_DETAIL='Fact-checked public information assembled into a full Signature-system database record; labeled public-harvest.';
var REQUIRED=["name", "how_it_works", "key_points", "requirements", "standards", "citations"];
var DATA=[{"topic": "What Counts as a Fact Conflict", "cat": "conflict-types", "rank": 1, "tier": "Foundations", "name": "fact-conflict-definition", "desc": "A fact conflict exists when two or more records, sources, or claims about the same entity and attribute disagree in a way that cannot both be true at once. This record defines the working vocabulary of conflict analysis: contradiction (mutually exclusive claims), disagreement (different values within the same scale), uncertainty (claims hedged by their sources), and irreconcilable difference (no shared ground). Naming the conflict type first is what makes every downstream procedure — comparison, provenance checks, and reconciliation — possible and repeatable.", "body": {"how_it_works": "The analyst takes every disputed claim pair and runs it through the conflict classifier. First, both claims are normalized to the same entity, attribute, unit, and time scope; claims that cannot be normalized are set aside as non-comparable rather than forced into conflict. Then the classifier checks: are the claims mutually exclusive (one true means the other false)? If yes, this is a contradiction and enters the contradiction pipeline. If the values differ but could coexist within measurement error, it is a disagreement and enters tolerance-band analysis. If either claim is hedged (\"approximately\", \"reportedly\"), it is uncertainty and enters provenance assessment. Finally the conflict is logged with its type, the normalized claims, and the classification reason, so any reviewer can reproduce the decision.", "key_points": ["Conflict must be about the same entity, attribute, unit, and time scope or it is not a conflict at all.", "Contradiction, disagreement, uncertainty, and irreconcilable difference need different procedures — never mix them.", "Normalization before classification: convert units, resolve aliases, align time scopes.", "Log the classification reason; a conflict decision that cannot be reproduced is just an opinion."], "requirements": "A controlled vocabulary for claims (entity, attribute, unit, time scope); a normalization checklist; a written classification rubric applied by every analyst the same way.", "standards": "Conflicts are typed at intake; untyped conflicts may not enter reconciliation. Every classification decision is recorded with its evidence and reviewer.", "citations": ["Data on the Web Best Practices: Data Quality Vocabulary (W3C, 2017)", "Knowledge Graph fact-checking literature: entity-attribute normalization"]}}, {"topic": "The Three Conflict Shapes", "cat": "conflict-types", "rank": 1, "tier": "Foundations", "name": "three-conflict-shapes", "desc": "Every fact conflict takes one of three shapes: direct contradiction (two claims that cannot both be true), value disagreement (claims on the same scale that differ beyond tolerance), or source-level conflict (two sources disagree about which claim is right, even if each source is internally consistent). Recognizing the shape tells the analyst which tool to reach for: contradiction logic, measurement-tolerance analysis, or source-reliability assessment. This record gives field tests for each shape with worked examples.", "body": {"how_it_works": "Shape test one is the exclusivity test: write claim A and claim B as formal statements and ask whether a world exists where both are true; if no such world exists, the shape is direct contradiction. Shape test two is the tolerance test: express both claims as values on one scale with their uncertainty bands; if the bands overlap, the difference may be measurement noise, but if they do not overlap, it is a genuine value disagreement. Shape test three is the source test: check whether the conflict lives inside one source or only between sources; when each source is self-consistent but sources disagree, the shape is source-level conflict and the remedy is provenance work, not logic. The analyst runs the three tests in order and records which test fired.", "key_points": ["Direct contradiction = no possible world holds both claims; resolve with logic and provenance.", "Value disagreement = bands do not overlap; resolve with measurement review and tolerance policy.", "Source-level conflict = each source internally consistent; resolve with source reliability assessment.", "Run the tests in order; most \"contradictions\" turn out to be disagreements or non-comparable claims."], "requirements": "Ability to restate claims formally; a defined tolerance for the attribute under dispute; access to the sources' full context, not just the disputed lines.", "standards": "Shape must be determined before any resolution attempt. Exclusivity claims must be justified in writing.", "citations": ["Stanford Encyclopedia of Philosophy: Contradiction (public reference)", "ISO 8000 data quality: master data accuracy tolerances"]}}, {"topic": "Conflicting Records: The Side-by-Side Method", "cat": "conflict-types", "rank": 1, "tier": "Foundations", "name": "side-by-side-comparison", "desc": "The side-by-side method lays conflicting records out in aligned columns — claim, source, timestamp, provenance, and confidence — so differences are visible instead of argued about. It is the first practical tool in conflict work and the one every other procedure assumes. This record teaches the layout, the comparison protocol, and the common mistakes: comparing different attributes, hiding timestamps, and summarizing instead of quoting. A clean side-by-side turns a heated dispute into a checklist.", "body": {"how_it_works": "Build a comparison table with one row per source and fixed columns: the exact claim quoted verbatim, the source name, the publication or recording timestamp, the provenance chain (who observed or measured), and the stated confidence. Align the rows so the same attribute is being compared — if one source reports meters and another reports feet, convert first and mark the conversion. Highlight only the cells that differ; identical cells are context, not conflict. Then walk the differences left to right: is the difference in the value itself, in the timestamp, in the provenance, or in the confidence? Write the answer for each differing cell. The finished table plus the per-cell answers is the conflict brief that all later steps work from.", "key_points": ["Quote verbatim; paraphrase is where conflicts get invented.", "Fix the columns: claim, source, timestamp, provenance, confidence — always these five.", "Convert units and scopes before comparing, and mark every conversion.", "The output is a conflict brief, not a verdict: differences listed, each explained."], "requirements": "Full text of each conflicting record; a table template; discipline to quote rather than summarize.", "standards": "No comparison without the five columns. Every unit conversion recorded in the brief.", "citations": ["Comparative analysis methods in journalism fact-checking guides", "Evidence table practice from systematic review methodology (Cochrane-style)"]}}, {"topic": "Source Reliability: The Provenance Questionnaire", "cat": "provenance-assessment", "rank": 1, "tier": "Foundations", "name": "provenance-questionnaire", "desc": "Before trusting a source, ask it twelve questions: who made it, when, why, from what original material, how many hands it passed through, whether it was revised, what it omits, who paid for it, what it has gotten wrong before, whether it can be corroborated, whether it shows its work, and whether it corrects itself. This record is the questionnaire with guidance for scoring each answer. It is the cheapest reliability test in the field — ten minutes of questions can retire hours of argument.", "body": {"how_it_works": "For each of the twelve questions, find the answer in the source itself or in its documented history; an unanswerable question is itself a finding (the source is opaque on that point). Score each answer as strong, acceptable, weak, or unknown, using the rubric notes in this record. Pay special attention to the chain question: every hand a claim passes through is a chance to distort it, and a source that cannot name its chain is weaker than one that can. Also weigh the corrections question heavily — a source with a public corrections record is more trustworthy than one that claims to be infallible, because correction behavior predicts future accuracy. The twelve scores form a reliability profile, not a single number; two sources can have the same average and very different weak points.", "key_points": ["Twelve questions: who, when, why, from what, through whom, revised?, omissions, funding, error history, corroboration, method shown, corrections.", "\"Unknown\" is a score — opacity is evidence of weakness.", "A public corrections record is a strength, not an embarrassment.", "Use the profile, not an average: two sources can match on average and differ on the question that matters."], "requirements": "The questionnaire rubric; access to source metadata and correction histories; honest \"unknown\" markings.", "standards": "No source used in a decision without a completed questionnaire. Unknowns flagged, never silently dropped.", "citations": ["IFLA: How to Spot Fake News (evaluation criteria, public reference)", "Archival provenance principles (Society of American Archivists, public reference)"]}}, {"topic": "Citation Integrity Basics", "cat": "provenance-assessment", "rank": 1, "tier": "Foundations", "name": "citation-integrity", "desc": "A citation is only as good as its chain: does the cited source actually say what the citing source claims, does it say it in the same sense, and is the chain unbroken back to the original? This record teaches the three-click citation check: open the citation, read the cited passage in context, and repeat toward the original. Broken chains — where A cites B, B cites C, and C says something different — are one of the most common sources of false conflicts, and the three-click check dissolves them in minutes.", "body": {"how_it_works": "Take the disputed claim and follow its citations one level at a time. At each level, read the cited passage in its original context and answer three questions: does it exist (the source really contains this text or data)? does it match (it says what the citer claims, in the same sense and scope)? does it stand (the source is itself credible on this point)? If any answer is no, the chain is broken at that level and the conflict may be a citation artifact rather than a real disagreement. Continue one more level past the first break to document how the distortion happened — telephone-game drift, scope narrowing, or outright fabrication. Conflicts that dissolve under the three-click check are recorded as citation failures, not fact conflicts, and the record is corrected at the citing level.", "key_points": ["Three questions per link: exists? matches? stands?", "Citation drift is the leading cause of phantom conflicts.", "Go one level past the break to document how the distortion happened.", "Record dissolved conflicts as citation failures so the same break is not re-investigated."], "requirements": "Access to the cited sources at each level; patience to read context, not just the quoted line.", "standards": "High-stakes claims must survive the three-click check. Broken chains are corrected at the citing level, not just noted.", "citations": ["Retraction Watch / citation integrity coverage (public reference)", "Scholarly citation practice guides (public reference)"]}}, {"topic": "Temporal Facts: Timestamps as Disambiguation", "cat": "temporal-truth", "rank": 1, "tier": "Foundations", "name": "timestamps-disambiguation", "desc": "Half of all fact conflicts are not contradictions at all — they are the same fact at different times. \"The CEO is X\" was true in 2019 and false in 2024; both records are correct once their timestamps are honored. This record teaches the timestamp-first reading habit: before declaring a conflict, check whether the claims differ in when they were true. It covers observation time versus recording time, timezone traps, version timestamps, and the phrase \"as of\" as the cheapest disambiguation tool ever invented.", "body": {"how_it_works": "For each claim, recover two timestamps: when the fact was observed or true (valid time) and when the record was written (transaction time); these can differ by years, and confusing them manufactures conflicts. Then compare the claims on a timeline: if claim A was true during interval X and claim B was true during interval Y, and the intervals do not overlap, there is no conflict — the answer is the time-indexed pair (X, Y). Only when the valid-time intervals overlap does a genuine conflict exist. Watch for timezone traps (a \"same-day\" conflict across zones) and for records that restate old facts without fresh observation — a 2024 article repeating a 2019 number inherits the 2019 valid time, not 2024. The resolution output is always time-indexed: \"true from X to Y, then Z\", never a bare winner.", "key_points": ["Valid time (when true) vs transaction time (when written) — recover both.", "Non-overlapping valid-time intervals mean no conflict; the answer is the time-indexed pair.", "Republication does not refresh valid time: a 2024 repeat of a 2019 fact is still 2019 data.", "\"As of <date>\" is the cheapest disambiguation tool available."], "requirements": "Timestamp fields on every record; a timeline view; unit conversion of date formats and timezones.", "standards": "No conflict declared until valid-time overlap is checked. Resolution outputs are time-indexed.", "citations": ["Temporal database theory: valid time vs transaction time (Snodgrass, public reference)", "ISO 8601 date/time representation"]}}, {"topic": "Primary vs Secondary Sources", "cat": "provenance-assessment", "rank": 1, "tier": "Foundations", "name": "primary-vs-secondary", "desc": "A primary source observed the fact directly; a secondary source reports someone else's observation. When they conflict, the primary source usually wins — but \"usually\" is doing real work here, because primaries can be misread, biased, or superseded by better later measurement. This record defines the primary-secondary-tertiary ladder, explains the five exceptions where a secondary beats a primary, and gives the downgrade rule: a conflict between a primary and its own secondary is a game of telephone, not a genuine dispute.", "body": {"how_it_works": "Classify each conflicting source as primary (direct observation or measurement), secondary (reports a primary, possibly with analysis), or tertiary (compiles secondaries). In the default rule, primary beats secondary beats tertiary, because each layer adds distortion risk. Then check the five exceptions: (1) the primary is known to be corrupted or coerced; (2) the secondary had access to multiple primaries the analyst lacks; (3) the primary's instruments were later shown to be miscalibrated; (4) the secondary corrects a known primary error with documented evidence; (5) the \"primary\" is actually someone's memory decades later while the secondary used contemporary records. If an exception applies and is documented, the hierarchy inverts for that case. A conflict between a primary and a secondary that merely repeats it is not resolved — it is dissolved, because there is only one real observation.", "key_points": ["Default ladder: primary > secondary > tertiary, by distortion risk.", "Five documented exceptions can invert the ladder — document which one applies.", "A primary and its own echo are one observation, not two votes.", "\"Memory primary\" decays: contemporary secondary beats decades-later recollection."], "requirements": "Source classification for every conflicting record; the five-exception checklist; documentation of any hierarchy inversion.", "standards": "Hierarchy inversions must cite the exception number and evidence. Echoes of a single observation are merged, not counted.", "citations": ["Historical method: primary/secondary source classification (public reference)", "Oral history reliability literature (public reference)"]}}, {"topic": "Source Reliability Scoring: The 0-100 Rubric", "cat": "provenance-assessment", "rank": 2, "tier": "Compounded", "name": "reliability-scoring", "desc": "The provenance questionnaire gives a profile; this record turns the profile into a defensible 0–100 score. Five dimensions — provenance transparency, method quality, correction behavior, corroboration history, and independence — each score 0 to 20, with anchored rubrics so two analysts score the same source within five points. The score is a decision aid, not a verdict: it ranks sources for weighting in reconciliation, and its dimension breakdown shows exactly why a source is trusted or doubted. This record includes the full anchored rubric and a worked scoring example.", "body": {"how_it_works": "Score each of the five dimensions 0–20 using the anchored rubric: 0–4 means absent or adverse evidence, 5–9 weak, 10–14 acceptable, 15–17 strong, 18–20 exemplary, with concrete anchor descriptions per dimension (for example, provenance transparency 18–20 requires a named observer, a dated record, and an unbroken chain to the original). Sum for the 0–100 total. Then sanity-check the total against a forced ranking: list all sources best-to-worst by gut feeling and confirm the scores agree; where they disagree, the rubric — not the gut — usually needs a re-read, and the discrepancy itself is informative. Use the total as the source's initial weight in reconciliation procedures, but always carry the dimension breakdown alongside it: a source scoring 70 via high method quality but low independence behaves very differently in a correlated-source dispute than a 70 with the reverse profile.", "key_points": ["Five dimensions x 0–20 with anchored descriptions: provenance, method, corrections, corroboration, independence.", "Calibrate with forced ranking: rubric score vs gut ranking; investigate disagreements.", "The score is a weighting input; the dimension breakdown is the explanation.", "Re-score when new evidence arrives — scores are living, not permanent."], "requirements": "The anchored rubric; at least two independent scorers for high-stakes sources; a record of the scoring session.", "standards": "Scores must cite evidence per dimension. Re-scoring triggered by new provenance evidence.", "citations": ["Source criticism rubrics in intelligence analysis (public methodology references)", "Inter-rater reliability practice (Cohen's kappa application)"]}}, {"topic": "Recency vs Authority Trade-offs", "cat": "temporal-truth", "rank": 2, "tier": "Compounded", "name": "recency-vs-authority", "desc": "The newer source says one thing; the more authoritative source says another. Recency and authority pull in opposite directions, and neither wins by default — the tie-breaker is the fact's half-life. Fast-changing facts (prices, office-holders, software versions) favor recency; slow-changing facts (founding dates, physical constants, historical events) favor authority. This record gives the half-life heuristic, the obsolescence check, and the hybrid answer: time-index both claims and let each win its own era.", "body": {"how_it_works": "First, estimate the fact's half-life: how quickly does this kind of fact change? For fast-decay facts, weight the newer source heavily and treat the older authoritative claim as \"was true\"; for slow-decay facts, weight the authoritative source and treat the newer claim as the one needing corroboration. Second, run the obsolescence check on the older source: was it superseded by its own later edition, or does it still stand as the source's current position? An authority that has updated itself is recency and authority in one. Third, if both survive, produce the time-indexed answer: \"Authoritative source says X as of 2019; recent source says Y as of 2024\" — and check whether Y could be a genuine change rather than a contradiction. The trade-off is resolved by time-indexing, not by picking a winner.", "key_points": ["The tie-breaker is the fact's half-life, not a fixed rule.", "Fast-decay facts favor recency; slow-decay facts favor authority.", "An authority that updated itself is both — check for superseding editions.", "When both survive, time-index: each claim wins its own era."], "requirements": "A half-life estimate for the fact class; obsolescence check on older sources; timeline presentation.", "standards": "Recency-vs-authority decisions must state the assumed half-life. Never silently drop the losing claim.", "citations": ["Information currency in reference work evaluation (public reference)", "Temporal validity concepts from bitemporal databases"]}}, {"topic": "Conflicting Numerical Records", "cat": "conflict-types", "rank": 2, "tier": "Compounded", "name": "numerical-conflicts", "desc": "Numbers conflict differently from words: 12,400 vs 12,500 may be the same fact rounded differently, while 12,400 vs 124,000 is a different fact or a typo. This record teaches the numerical conflict protocol: check units and scale factors, check rounding and precision, check for transposition and decimal-slip typos, check whether the numbers measure the same thing, and only then treat the difference as genuine. Most numerical \"contradictions\" dissolve at step one or two.", "body": {"how_it_works": "Work the five checks in order. (1) Units and scale: convert to common units and check for thousand/million/billion slips — the most common numerical conflict cause. (2) Rounding and precision: if both values round to the same number at the stated precision, they agree; record the shared value with the precision noted. (3) Typo patterns: compare digit-by-digit for transpositions (124 vs 142), decimal slips (12.4 vs 124), and dropped digits — one-digit differences in long numbers are typo suspects. (4) Definition match: confirm both numbers count the same thing over the same population and period — \"users\" vs \"active users\" vs \"registered accounts\" are different facts that look like one. (5) Only if all four pass is the difference genuine, and then it enters measurement-error analysis: each number gets an uncertainty band, and non-overlapping bands mean a real disagreement needing provenance work.", "key_points": ["Order matters: units, rounding, typos, definitions — then genuine difference.", "Scale slips (thousand vs million) are the #1 cause of numerical conflicts.", "Different definitions wearing the same label are different facts.", "Genuine differences become uncertainty bands; overlapping bands may still agree."], "requirements": "Both numbers with full units, precision, definitions, and provenance; a unit-conversion checklist.", "standards": "No numerical conflict is declared genuine until all four artifact checks are documented.", "citations": ["Benford's law applications in data validation (public reference)", "Measurement uncertainty guides (NIST, public reference)"]}}, {"topic": "Name Collisions and Entity Resolution", "cat": "conflict-types", "rank": 2, "tier": "Compounded", "name": "entity-resolution", "desc": "Two records say different things about \"John Smith\" — but are they the same John Smith? Name collisions manufacture conflicts out of thin air when records about different entities are merged, and they hide real conflicts when records about one entity are split. This record teaches entity resolution: the attribute-signature method, disambiguation keys (birth date, location, identifiers), and the merge/split decision protocol. In conflict work, entity resolution comes before fact comparison — you cannot resolve a conflict between records that are not about the same thing.", "body": {"how_it_works": "Build an attribute signature for each record: name plus every disambiguating attribute available (dates, places, identifiers, affiliations, relationships). Compare signatures with the blocking-and-scoring method: first block obviously-different records apart (different countries, impossible date overlaps), then score the remaining pairs on shared attributes with weights (a matching national ID outweighs a matching first name). Pairs above the merge threshold are treated as one entity and their facts enter conflict analysis; pairs below the split threshold stay separate and the \"conflict\" is closed as a collision. Pairs in the middle are held as uncertain — flagged, not forced — because a forced merge creates false conflicts and a forced split hides true ones. Every merge/split decision is logged with its score and the attributes that drove it.", "key_points": ["Entity resolution precedes fact comparison — always.", "Attribute signatures: name plus every disambiguating attribute you can find.", "Hold the middle: uncertain pairs are flagged, never forced.", "Log every merge/split with its score; resolutions must be reversible."], "requirements": "Disambiguating attributes for each record; a scoring rubric with attribute weights; merge/split thresholds.", "standards": "Forced merges/splits are prohibited. Resolution decisions logged and reversible.", "citations": ["Entity resolution / record linkage literature (Fellegi-Sunter model, public reference)", "Deduplication methodology in data integration (public reference)"]}}, {"topic": "Contradictory Dates and Event Ordering", "cat": "temporal-truth", "rank": 2, "tier": "Compounded", "name": "date-conflicts", "desc": "Event A is dated 1847 by one source and 1849 by another. Date conflicts are resolved with a special toolkit because dates carry their own failure modes: calendar systems (Julian vs Gregorian), year-start conventions, transcription errors in handwritten records, and \"circa\" ranges treated as points. This record gives the date-conflict protocol: normalize calendars, widen \"circa\" to ranges, check relative ordering constraints (A must precede B), and use ordering as a cross-check — if both dates agree on order but not year, the conflict is narrower than it looks.", "body": {"how_it_works": "First normalize all dates to one calendar and one notation (ISO 8601 internally), recording every conversion; Julian/Gregorian slips alone explain centuries of \"conflicts\" in early modern records. Second, convert every \"circa\", \"about\", and \"early/late\" qualifier into an explicit range — a circa-1847 (1845–1849) and a firm 1849 overlap, which downgrades the conflict to an imprecision. Third, apply ordering constraints from the narrative: if both sources agree that event A preceded event B, any date assignment violating that order is suspect regardless of its source's authority. Fourth, check the digit level: 1847 vs 1849 is a one-digit transcription suspect, especially in handwritten or OCR'd sources. The output is a constrained date range plus an ordering graph, which often resolves the practical question (what happened first?) even when the exact years stay uncertain.", "key_points": ["Normalize calendars first: Julian/Gregorian slips explain centuries of phantom conflicts.", "Expand qualifiers to ranges: circa-1847 is 1845–1849, not a point.", "Ordering constraints cross-check dates: agreed sequence beats disputed years.", "One-digit differences in old records are transcription suspects."], "requirements": "Calendar identification for each source; a qualifier-to-range table; the event ordering graph.", "standards": "All dates stored with calendar and qualifier metadata. Outputs are ranges, never false precision.", "citations": ["Calendar conversion references (public)", "Historical dating methodology (public reference)"]}}, {"topic": "Version Conflict in Documents", "cat": "conflict-types", "rank": 2, "tier": "Compounded", "name": "version-conflicts", "desc": "Two copies of the \"same\" document say different things. Version conflicts arise from drafts mistaken for finals, unauthorized edits, merged branches, and silent revisions. The resolution starts with version forensics: which copy is authoritative, what changed between them, and whether the changes are corrections or corruptions. This record covers the diff-first method, the authority hierarchy of versions (signed final > published > draft > copy), and the merge-artifact check for documents assembled from pieces.", "body": {"how_it_works": "Gather every available version and order them by the version timeline, using embedded dates, revision marks, and provenance — not filenames, which lie. Diff adjacent versions to produce the change list: every insertion, deletion, and alteration with its location. Classify each change: correction (fixes a known error, ideally documented), update (new information), corruption (introduces error), or unknown. The authority hierarchy then applies: a signed or sealed final outranks a published copy, which outranks a draft, which outranks an unattributed copy — but a documented correction in a lower version can still beat a higher version's error, and that exception must be written down. For assembled documents, check each section's version independently: a clean whole can hide a corrupted chapter. The resolution names the canonical version and lists every deviation in the others.", "key_points": ["Order versions by embedded evidence, not filenames.", "Diff first, judge second: the change list is the raw material.", "Authority hierarchy: signed final > published > draft > copy — with a documented-correction exception.", "Check assembled documents section by section."], "requirements": "All available versions; a diff tool or manual diff protocol; the version authority rubric.", "standards": "Canonical version declared explicitly with the deviation list. Silent revisions flagged when found.", "citations": ["Version control concepts (public reference)", "Textual criticism methodology (stemmatics, public reference)"]}}, {"topic": "Witness Testimony vs Instrumental Data", "cat": "provenance-assessment", "rank": 2, "tier": "Compounded", "name": "testimony-vs-instruments", "desc": "The witness says the car was blue; the camera says it was green. Human testimony and instrumental records conflict with special regularity because they fail differently: memory reconstructs, instruments miscalibrate. This record gives the failure-mode comparison — what each source type gets wrong — and the adjudication protocol: check instrument calibration and chain of custody first (instruments are auditable), then check witness conditions (lighting, distance, stress, delay), and treat the conflict as a measurement problem on both sides rather than a credibility contest.", "body": {"how_it_works": "Audit the instrument side first because it is the more checkable side: calibration records, maintenance logs, chain of custody from capture to presentation, and whether the instrument's limits (resolution, color balance, range) cover the disputed point. A camera with a documented white-balance fault loses to a witness on color. Then audit the witness side with the conditions checklist: observation conditions (light, distance, duration), delay before the statement, stress level, prior expectations, and consistency across the witness's own retellings — internal inconsistency is the strongest witness-side signal. When both sides have weaknesses, look for a third anchor: another instrument, another witness, or a physical trace. The verdict format is always comparative: \"instrument favored because calibration is current and the witness observed for two seconds at dusk,\" never a bare winner.", "key_points": ["Audit instruments first: calibration, custody, and limits are checkable.", "Audit witnesses on conditions: light, distance, delay, stress, consistency.", "Instruments fail on calibration; humans fail on reconstruction — check each on its own failure mode.", "Verdicts are comparative and reasoned, never bare winners."], "requirements": "Instrument calibration/custody records; witness conditions checklist; a third anchor when both sides are weak.", "standards": "No dismissal of either side without its audit. Verdicts cite the specific audit findings.", "citations": ["Eyewitness reliability research (public reference, e.g., Innocence Project summaries)", "Forensic instrument validation practice (public reference)"]}}, {"topic": "Expert Disagreement Protocols", "cat": "consensus-methods", "rank": 2, "tier": "Compounded", "name": "expert-disagreement", "desc": "Two genuine experts disagree. This is normal — expertise does not converge on open questions — and the protocol for handling it is different from ordinary conflict resolution because neither side can be dismissed on reliability grounds. This record covers the disagreement map (do they disagree on facts, methods, or interpretation?), the structured-expert-judgment toolkit (Delphi rounds, adversarial collaboration), and the honest output format: a quantified disagreement with each expert's reasons, not a false consensus.", "body": {"how_it_works": "First map the disagreement precisely: separate disputed facts from disputed methods from disputed interpretations — experts often agree on facts and disagree on what follows, which is a smaller conflict than it appears. Then check for shared-evidence gaps: is one expert missing a study the other has? Filling the gap resolves a surprising share of expert disputes. If the disagreement survives, run a structured round: each expert states their position with reasons and uncertainty, reads the other's, and revises — one Delphi-style round, documented. Adversarial collaboration is the stronger variant: the experts jointly design the test that would settle it. The final output quantifies the disagreement (e.g., expert A: 70% for hypothesis X; expert B: 65% for hypothesis Y) with both reason sets attached. Forcing consensus where none exists is a failure mode; the honest disagreement is the product.", "key_points": ["Map the disagreement: facts vs methods vs interpretation — smaller than it looks.", "Check for shared-evidence gaps before treating it as a deep dispute.", "One structured revision round; adversarial collaboration where stakes justify it.", "Output quantified disagreement with reasons — never forced consensus."], "requirements": "Both experts' positions with reasons and uncertainty; a facilitator for the structured round; documentation of revisions.", "standards": "Disagreement maps required before any synthesis. Forced consensus is a documented failure.", "citations": ["Structured expert judgment literature (Cooke method, public reference)", "Adversarial collaboration (Kahneman & Klein, public reference)"]}}, {"topic": "Time-Dependent Facts: Facts That Were True", "cat": "temporal-truth", "rank": 2, "tier": "Compounded", "name": "facts-that-were-true", "desc": "Some facts expire: populations, prices, office-holders, rankings, borders, and records. Treating an expired fact as a contradiction — or worse, as a lie — is one of the most common errors in conflict work. This record teaches the expiry-aware method: attach valid-time intervals to every time-sensitive fact, distinguish genuine change from correction (the old fact was wrong vs the world changed), and build the fact's timeline as the resolution. The timeline is not a compromise; it is the correct answer.", "body": {"how_it_works": "For each conflicting claim about a time-sensitive attribute, determine its valid-time interval: the period during which the claim was true. Then classify the transition between the old and new claims: genuine change (the world moved — new election, new price), correction (the old record was wrong and the new one fixes it), or refinement (the new claim is more precise about the same state). Genuine changes produce a timeline with both claims true in their intervals — no conflict at all. Corrections require the old record to be marked superseded-with-cause, preserving it for audit while retiring it from use. Refinements merge into a single more precise claim. The key discipline is the world-vs-record question: did the world change, or did our record of the world change? Answering it correctly determines whether you build a timeline, issue a correction, or merge.", "key_points": ["Expiry is normal: attach valid-time intervals to time-sensitive facts.", "Classify transitions: genuine change vs correction vs refinement.", "Genuine change = timeline, both true in their intervals. Correction = supersede with cause.", "The world-vs-record question decides the procedure."], "requirements": "Valid-time intervals for each claim; the transition classifier; a supersession marking convention.", "standards": "Superseded records preserved for audit, retired from use. Timelines are the default output for expired facts.", "citations": ["Slowly changing dimensions (data warehousing, public reference)", "Revision and errata practice in reference publishing (public reference)"]}}, {"topic": "Retracted Claims and Corrections", "cat": "temporal-truth", "rank": 2, "tier": "Compounded", "name": "retractions-corrections", "desc": "A retracted claim is a special conflict: the source itself has withdrawn it. Retractions outrank almost everything — a source's own correction is the strongest possible evidence against its earlier claim — yet retracted claims keep circulating because downstream copies never get the memo. This record covers the retraction hierarchy (retraction > correction > original), the propagation problem, and the retraction-check protocol: before using any high-stakes claim, check whether its source has retracted or corrected it, and mark downstream copies accordingly.", "body": {"how_it_works": "Maintain a retraction watchlist for the sources and claims in active use: check publisher retraction notices, correction logs, and errata pages on a schedule matched to the stakes. When a conflict involves a claim whose source has retracted it, the resolution is immediate — the retracted claim loses, full stop — and the work shifts to propagation: finding downstream copies of the retracted claim and marking them retracted-at-source. Distinguish full retraction (the claim is withdrawn) from correction (the claim is replaced by a corrected version) from expression of concern (the claim is under review): each has a different handling rule, and conflating them creates new errors. For corrections, the corrected version inherits the original's citations plus the correction notice, so the chain stays traceable. The standing rule: no claim is used in a decision without a retraction check within its freshness window.", "key_points": ["Retraction hierarchy: retraction > correction > original — a source's own withdrawal is decisive.", "Retracted claims keep circulating: the work is propagation, not just the ruling.", "Distinguish retraction vs correction vs expression of concern.", "Retraction check is mandatory before high-stakes use."], "requirements": "Retraction watchlist; access to publisher correction logs; a downstream-marking procedure.", "standards": "Retracted claims may not be used except as examples of retraction. Corrections carry both the new claim and the notice.", "citations": ["Retraction Watch database (public reference)", "COPE retraction guidelines (public reference)"]}}, {"topic": "Duplicate Records With Different Values", "cat": "conflict-types", "rank": 3, "tier": "Compounded", "name": "duplicate-value-conflicts", "desc": "The same record appears twice with different values — a database has two rows for one entity, a bibliography lists two publication years for one paper. These are dedup conflicts, and they resolve with the survivor rule: determine which copy is authoritative, merge the best fields from each, and retire the loser with a tombstone. This record covers duplicate detection (fuzzy matching on identifiers), the survivor hierarchy (most complete, most recent correction, best provenance), field-level merging, and tombstoning so the duplicate never resurrects.", "body": {"how_it_works": "First confirm the duplication with identifier matching: shared IDs, near-identical titles, or matching fingerprints mean one entity with two rows, not two entities. Then pick the survivor using the hierarchy: the copy with the best provenance wins; among equals, the most recently corrected wins; among those, the most complete wins. Merge field-by-field rather than row-by-row: the survivor takes each field's best value, and every adopted field records its source copy — a merged record is a mosaic with a manifest. The losing copy is not deleted; it is tombstoned (marked duplicate-of the survivor with the merge date and reason), because deletion resurrects duplicates when the data is re-imported. Finally, fix the process that created the duplicate — the dedup is a symptom — or the next import will recreate it.", "key_points": ["Confirm duplication with identifiers before merging — never merge on vibes.", "Survivor hierarchy: provenance, then recency-of-correction, then completeness.", "Merge field-by-field with a manifest; the survivor is a documented mosaic.", "Tombstone, don't delete — and fix the process that made the duplicate."], "requirements": "Identifier/fingerprint matching; the survivor hierarchy; tombstone markers; a fix for the duplicate source.", "standards": "All merges carry a field-level manifest. Deletion of duplicates is prohibited; tombstoning required.", "citations": ["Deduplication in master data management (public reference)", "Slowly changing dimensions type 2 (history-preserving merges)"]}}, {"topic": "Partial Contradictions: Overlap Analysis", "cat": "reconciliation", "rank": 3, "tier": "Compounded", "name": "partial-contradictions", "desc": "Most real conflicts are partial: the sources agree on 80% and clash on 20%. Treating a partial contradiction as total — discarding everything — wastes the agreement; treating it as minor — ignoring the clash — risks the decision. Overlap analysis decomposes the conflict into its agreed core and its disputed remainder, resolves each part with the right tool, and reassembles. This record teaches the decomposition protocol and the reassembly rule: the agreed core is banked first, then the disputed remainder gets the full conflict procedure.", "body": {"how_it_works": "Decompose both claims into atomic propositions — the smallest statements that can be true or false independently. Sort the atoms into three piles: agreed (both sources affirm), disputed (sources affirm opposites), and unique (only one source mentions it). Bank the agreed pile immediately: it becomes the settled core, cited by both sources, and it constrains the resolution — any proposed resolution of the disputed pile must remain consistent with the settled core. Run the full conflict procedure only on the disputed pile, which is usually far smaller than the original claims. Handle the unique pile with corroboration checks: an uncorroborated unique atom is flagged, not banked. Reassemble into a single resolved record: settled core + resolved disputes + flagged uniques, each part labeled with its status. The reassembly is reviewed as a whole for internal consistency before it ships.", "key_points": ["Decompose into atomic propositions; sort into agreed, disputed, unique.", "Bank the agreed core first — it constrains everything after.", "Only the disputed pile gets the full procedure; it is usually small.", "Reassemble with status labels and a final consistency review."], "requirements": "Atomic decomposition skill; the three-pile sort; a reassembly review step.", "standards": "No resolution without decomposition. Settled cores cited to both sources.", "citations": ["Argument mapping / decomposition methods (public reference)", "Requirements traceability decomposition practice (public reference)"]}}, {"topic": "Majority Vote vs Weighted Evidence", "cat": "consensus-methods", "rank": 3, "tier": "Compounded", "name": "majority-vs-weighted", "desc": "Five sources say X, two say Y — does X win? Only if the five are independent. Majority vote is the crudest consensus method and the most abused: it counts echoes as votes, ignores reliability differences, and fails exactly when sources copy each other. Weighted evidence fixes all three by weighting each source's vote by reliability and independence. This record compares the methods, gives the independence discount rule, and states when majority vote is acceptable (low stakes, verified independence) versus when weighting is mandatory.", "body": {"how_it_works": "First test independence: trace each source's provenance chain and discount any source that derives from another counted source — a copy is not a vote, and the discount is total (weight zero) for pure echoes, partial for sources sharing some but not all upstream material. Then assign reliability weights from the 0–100 rubric scores. The weighted tally is the sum of weights for each claim; the winner is the claim with the highest weighted sum, and the margin is reported as the weight ratio, not a vote count. Majority vote is permitted only when all three conditions hold: stakes are low, independence is verified (not assumed), and reliability differences are small — and even then the vote count is reported with the independence finding attached. When the weighted tally is close (ratio under 2:1), the honest output is \"unresolved leaning X,\" not a verdict.", "key_points": ["Count independence before counting votes: echoes are not votes.", "Weighted tally = sum of reliability weights per claim; report the ratio.", "Majority vote allowed only at low stakes with verified independence.", "Close tallies (under 2:1) are \"leaning,\" not verdicts."], "requirements": "Provenance chains for independence testing; reliability scores; the close-tally threshold policy.", "standards": "Independence must be verified, never assumed. Echoes discounted to zero weight.", "citations": ["Condorcet jury theorem and its independence assumption (public reference)", "Meta-analysis weighting methods (public reference)"]}}, {"topic": "Cross-Source Triangulation", "cat": "provenance-assessment", "rank": 3, "tier": "Compounded", "name": "triangulation", "desc": "Triangulation confirms a claim by approaching it from independent directions: different source types, different methods, different observers. A claim supported by a document, a measurement, and a witness is far stronger than a claim supported by three documents from the same archive. This record teaches triangulation design: pick axes of independence, seek the weakest axis, and know when triangulation has succeeded (convergent independent lines) versus when it has merely accumulated echoes.", "body": {"how_it_works": "Design the triangulation before collecting: choose at least three axes of independence relevant to the claim — for example, source type (document vs instrument vs testimony), method (direct measurement vs derived calculation), and observer (different people or institutions). Pursue each axis independently: do not let the document search steer the witness interviews. Score each axis's finding separately with its own reliability assessment. Convergence — independent axes agreeing — is the success condition, and its strength grows with the axes' independence, not their number: two truly independent axes beat five correlated ones. Divergence is informative too: when axes disagree, the disagreement pattern points at the weak axis (the witness diverges from both document and instrument — investigate the witness conditions). Document the triangulation as a small matrix: axes by findings, with independence justifications for each axis pair.", "key_points": ["Design axes of independence before collecting: type, method, observer.", "Pursue axes independently — no steering one search with another's results.", "Two independent axes beat five correlated ones.", "Divergence patterns identify the weak axis; document the matrix."], "requirements": "A triangulation plan with named axes; independent collection per axis; the convergence/divergence rubric.", "standards": "Independence of axes must be justified in writing. Triangulation matrices archived with the resolution.", "citations": ["Triangulation in social research methods (public reference)", "Independent verification in auditing standards (public reference)"]}}, {"topic": "Staleness Detection in Records", "cat": "temporal-truth", "rank": 3, "tier": "Compounded", "name": "staleness-detection", "desc": "A record can be perfectly accurate and completely wrong — accurate about the world as it was, wrong about the world as it is. Staleness detection asks whether a record's facts have expired since it was written. This record gives the freshness protocol: the fact-class half-life table, the change-signal watch (events that invalidate classes of facts), and the refresh-vs-retire decision. In conflict work, the stale record is the usual suspect whenever an old authority contradicts a new observation.", "body": {"how_it_works": "Look up the fact class in the half-life table to get the expected freshness window (prices: days; office-holders: tied to election cycles; physical constants: decades). Compare the record's valid time against the window: inside the window, treat the record as current; outside, flag it stale-pending-verification — not false, just unverified for now. Then check change signals: known events since the record's date that invalidate its class (an election invalidates office-holder facts; a product launch invalidates spec sheets). If a change signal fired, the record is stale-by-event and loses to any post-event source without further analysis. The refresh-vs-retire decision follows: high-value stale records get refreshed (re-observed and re-dated); low-value ones are retired to the archive with their valid-time interval intact. Conflicts where one side is stale-by-event are not genuine conflicts — they are timelines.", "key_points": ["Accurate-about-then vs wrong-about-now: staleness is the usual suspect.", "Half-life table gives the freshness window per fact class.", "Change signals (elections, launches) invalidate whole fact classes at once.", "Stale-vs-fresh conflicts are timelines, not contradictions."], "requirements": "The half-life table; a change-signal watchlist; refresh/retire criteria.", "standards": "Records used in decisions must be within their freshness window or re-verified. Stale-by-event rulings documented.", "citations": ["Data freshness / currency in data quality frameworks (public reference)", "Change data capture concepts (public reference)"]}}, {"topic": "Reconciliation Procedures: The Five-Step Pipeline", "cat": "resolution-procedures", "rank": 4, "tier": "Advanced", "name": "five-step-pipeline", "desc": "The five-step reconciliation pipeline is the standard end-to-end procedure for resolving fact conflicts: intake and normalization, conflict typing, provenance assessment, weighted resolution, and documented output. Each step has entry criteria, exit criteria, and a defined handoff, so a conflict can be paused, resumed, reviewed, or audited at any point. This record is the pipeline specification — the procedure that all the other records in this database plug into — with the gate rules that prevent skipping steps under pressure.", "body": {"how_it_works": "Step 1, intake and normalization: collect the conflicting claims, normalize entity/attribute/unit/time scope, and produce the side-by-side brief; exit criterion is a complete brief with no non-comparable pairs. Step 2, conflict typing: classify each pair with the shape tests (contradiction, disagreement, uncertainty); exit criterion is a typed conflict log. Step 3, provenance assessment: questionnaire, reliability scores, independence testing, and triangulation on the key claims; exit criterion is a scored, independence-checked source set. Step 4, weighted resolution: apply the resolution method matched to the conflict type (weighted tally for source-level, tolerance analysis for value disagreements, logic for contradictions); exit criterion is a resolution with stated method and margin. Step 5, documented output: the resolution record with method, evidence, margin, dissenting sources, and audit trail; exit criterion is a record a stranger could verify. Gates: no step may be skipped — under time pressure the steps shrink (a 10-minute triage still types before resolving) but never vanish.", "key_points": ["Five steps: intake, typing, provenance, resolution, documentation — each with exit criteria.", "Steps shrink under pressure but never vanish; typing before resolving is the inviolable gate.", "Every step's output is the next step's input — the pipeline is auditable end to end.", "The final record must be verifiable by a stranger."], "requirements": "The pipeline checklist with entry/exit criteria; templates for the brief, log, and resolution record; gate enforcement.", "standards": "Skipped steps invalidate the resolution. All five artifacts archived with the resolution.", "citations": ["Incident response pipeline structures (public reference)", "Scientific method as staged procedure (public reference)"]}}, {"topic": "Dempster-Shafer Evidence Combination", "cat": "consensus-methods", "rank": 4, "tier": "Advanced", "name": "dempster-shafer", "desc": "Dempster-Shafer theory combines evidence from multiple sources while honestly representing ignorance — a source can support claim X to degree 0.6 and remain uncommitted on the rest, instead of being forced to split belief between X and not-X. This makes it a natural fit for conflict resolution, where sources are often partial and overlapping. This record explains belief masses, the combination rule, and the conflict coefficient k that measures how much the sources disagree — including the famous caution: high conflict makes the combination rule behave strangely, so k is always reported alongside the result.", "body": {"how_it_works": "Each source assigns belief masses to sets of hypotheses: m({X}) = 0.6 means 0.6 of belief committed to X, with the remainder on larger sets (including the whole frame, meaning \"any of these\") representing ignorance. Dempster's rule combines two mass functions by multiplying masses of intersecting sets and renormalizing — except the mass assigned to the empty set, the conflict coefficient k, is computed first and reported. When k is low, the combined belief is a principled synthesis; when k is high (sources fundamentally disagree), the renormalization can produce counterintuitive results — the Zadeh paradox — so high-k combinations are flagged and the sources are sent back to provenance assessment instead of being combined. In practice: encode each source's claim as masses, combine pairwise, watch k at every step, and treat the combined belief as the weighted synthesis with k as the disagreement meter. The method's honesty about ignorance is its advantage over forced Bayesian priors.", "key_points": ["Belief masses can represent ignorance, not just X-vs-not-X.", "Dempster's rule combines by intersecting and renormalizing; k measures conflict.", "High k = do not trust the combination; send sources back to provenance work.", "Report k with every result — the disagreement meter is part of the answer."], "requirements": "The frame of discernment (hypothesis set); mass assignments per source with justification; a k-threshold policy.", "standards": "k always reported. Combinations with k above threshold require provenance re-work, not acceptance.", "citations": ["Dempster-Shafer theory (Shafer 1976, public reference)", "Zadeh's paradox caution on high-conflict combination (public reference)"]}}, {"topic": "Bayesian Updating Under Conflict", "cat": "consensus-methods", "rank": 4, "tier": "Advanced", "name": "bayesian-updating", "desc": "Bayesian updating treats conflicting sources as evidence that shifts belief: start with a prior, update with each source's likelihood, and the posterior is the reconciled belief. Its strength is principled handling of source reliability — an unreliable source simply has a flat likelihood and moves belief little. Its danger is false precision: exact-looking posteriors built on guessed priors and guessed likelihoods. This record gives the honest Bayesian protocol: justified priors, calibrated likelihoods, sensitivity analysis, and the rule that the posterior is always reported with the assumptions that built it.", "body": {"how_it_works": "State the prior explicitly with its justification — a neutral prior, a base rate, or a previous posterior — and write down why this prior and not another. For each source, specify the likelihood: the probability the source would report what it reported if each hypothesis were true; this is where reliability enters, as a calibrated number (a source right 80% of the time on this fact class has likelihood 0.8 for true reports). Update sequentially with Bayes' rule, or jointly for correlated sources — and check correlation first, because treating dependent sources as independent double-counts evidence. Then run sensitivity analysis: vary the prior and the likelihoods within their plausible ranges and check whether the conclusion survives; conclusions that flip under small changes are reported as fragile. The output is the posterior plus the full assumption list plus the sensitivity result — a posterior without its assumptions is numerology.", "key_points": ["Priors and likelihoods must be justified in writing — no smuggled numbers.", "Reliability enters as calibrated likelihoods; unreliable sources move belief little.", "Check source correlation before updating — dependent sources double-count.", "Sensitivity analysis decides whether the conclusion is robust or fragile."], "requirements": "Justified priors; calibrated likelihoods per source; correlation check; sensitivity analysis.", "standards": "Posteriors reported with full assumptions and sensitivity results. Fragile conclusions labeled fragile.", "citations": ["Bayesian reasoning introductions (public reference)", "Base-rate and calibration literature (public reference)"]}}, {"topic": "Truth Discovery Algorithms", "cat": "consensus-methods", "rank": 4, "tier": "Advanced", "name": "truth-discovery", "desc": "Truth discovery algorithms resolve conflicts across many sources at once by jointly estimating two unknowns: which claims are true and which sources are reliable. The insight is the feedback loop — reliable sources make true claims, and true claims come from reliable sources — iterated until both estimates stabilize. This record explains the iterative voting framework, the handling of the cold-start problem (no known truths yet), and the failure modes: correlated sources gaming the loop, and the majority-bias trap where the algorithm converges on the most-copied claim rather than the true one.", "body": {"how_it_works": "Initialize source reliability uniformly (cold start) or from known truths if any exist — even a handful of verified claims dramatically improves convergence. Then iterate: (a) estimate claim truth as the reliability-weighted support across sources; (b) re-estimate each source's reliability as its agreement with the current truth estimates; repeat until the estimates stop moving. After convergence, audit the result for the two failure modes: check source independence (correlated copiers inflate each other's reliability — apply the independence discount before iterating), and check for majority bias by testing whether the winning claims are also the most-copied rather than the best-sourced. Where ground truth exists for a sample, validate the algorithm's output against it and report the accuracy; where it does not, report the convergence margin and the independence audit instead of a bare answer. Truth discovery is powerful at scale and dangerous without the audits.", "key_points": ["Joint estimation: claim truth and source reliability refine each other iteratively.", "Cold start with uniform reliability; a few known truths help enormously.", "Audit for correlated copiers and majority bias before trusting convergence.", "Validate against ground-truth samples where they exist."], "requirements": "A claim-source matrix; independence audit; convergence criteria; ground-truth samples for validation.", "standards": "Independence audit mandatory before iteration. Majority-bias check on every run.", "citations": ["Truth discovery survey literature (public reference, e.g., Li et al.)", "Copying/dependence detection in data fusion (public reference)"]}}, {"topic": "Correlated Sources: Detecting Echo Chambers", "cat": "provenance-assessment", "rank": 4, "tier": "Advanced", "name": "echo-chamber-detection", "desc": "Ten sources agree — but nine copied the tenth. Correlated sources are the silent killer of consensus methods: every vote-counting, weighting, and truth-discovery procedure assumes independence, and echoes violate it. This record teaches echo detection: provenance-chain tracing to find the common ancestor, textual fingerprinting (identical distinctive errors are copying signatures), timing analysis (the earliest publisher is usually the origin), and the independence discount that neutralizes echoes once found.", "body": {"how_it_works": "Trace every source's provenance chain upward until it terminates at an original observation or a dead end; sources whose chains converge on one ancestor are one voice, not many. Then fingerprint: compare the sources' distinctive details — unusual phrasings, specific numbers, and especially errors. Shared distinctive errors are near-certain copying signatures, because two independent observers do not make the same unusual mistake. Timing analysis corroborates: the earliest publication with the distinctive content is the probable origin, and later matches are echoes unless they add independent detail. Once echoes are mapped, apply the independence discount: the echo cluster gets the weight of its single origin (not zero — the origin still counts — but the copies add nothing). Document the echo map as part of the resolution, because the next analyst will otherwise re-count the same ten \"sources.\"", "key_points": ["Trace chains to the common ancestor: convergent chains = one voice.", "Shared distinctive errors are copying signatures — independent observers don't share mistakes.", "Earliest distinctive publication is the probable origin.", "Echo clusters get the origin's weight, not the cluster's count."], "requirements": "Provenance chains for all sources; text-comparison for fingerprinting; publication timestamps.", "standards": "Echo maps documented with every multi-source resolution. Copying findings preserved for future analysts.", "citations": ["Information cascade literature (public reference)", "Plagiarism/copying detection methods (public reference)"]}}, {"topic": "Adversarial Sources: Intentional Disinformation", "cat": "provenance-assessment", "rank": 4, "tier": "Advanced", "name": "adversarial-sources", "desc": "Some sources do not merely err — they deceive. Adversarial sources plant false claims, forge provenance, and mimic reliable sources' surface features. This record covers the adversarial threat model for conflict resolution: motive-means-opportunity assessment, forgery detection (anachronisms, provenance gaps, too-perfect detail), the containment protocol (quarantine the source, audit everything it touched), and the hard rule — a caught-deceiving source's entire corpus is suspect, because selective trust in a liar is how the next deception lands.", "body": {"how_it_works": "Assess motive, means, and opportunity for each source in a high-stakes conflict: who benefits if this claim is believed, does the source have the capability to fabricate convincingly, and did it have unobserved opportunity? Then forensically examine the source's product: anachronisms (details from the wrong era), provenance gaps (\"a source who must remain unnamed\" with no verifiable chain), and too-perfect detail (real observations have noise; fabrications are often suspiciously clean). If deception is confirmed, trigger containment: quarantine the source (weight zero in all active resolutions), audit every resolution the source participated in, and mark its corpus tainted pending re-verification. The critical discipline is scope: one confirmed deception taints the source's whole corpus, because adversaries mix truth and lies — the true claims are camouflage. Report the finding plainly with the evidence; euphemism helps the deceiver.", "key_points": ["Threat model: motive, means, opportunity — assessed per source at high stakes.", "Forgery tells: anachronisms, provenance gaps, too-perfect detail.", "Containment: quarantine, audit everything the source touched, mark the corpus.", "One confirmed deception taints the whole corpus — selective trust is the trap."], "requirements": "The motive-means-opportunity checklist; forensic examination capability; a containment procedure with audit.", "standards": "Confirmed deception findings documented with evidence. Quarantined sources listed, never silently dropped.", "citations": ["Disinformation analysis frameworks (public reference)", "Source validation in intelligence methodology (public reference)"]}}, {"topic": "Knowledge Graph Consistency Repair", "cat": "resolution-procedures", "rank": 5, "tier": "Advanced", "name": "kg-consistency-repair", "desc": "When conflicting facts live in a knowledge graph, resolution becomes consistency repair: find the minimal set of changes that makes the graph satisfy its constraints. This record covers the repair framework — constraints as the law (functional dependencies, type constraints, temporal bounds), conflict detection as constraint violation, and minimal repair as the principle (change as little as possible, preferring changes to the least reliable assertions). It includes the provenance-priority rule: when two repairs are equally minimal, the one touching lower-reliability assertions wins.", "body": {"how_it_works": "Encode the domain constraints as machine-checkable rules: each entity has one birth date (functional dependency), populations are non-negative integers (type constraint), office terms do not overlap for one office (temporal constraint). Load the conflicting assertions and run violation detection — every violated constraint names its conflicting assertion set. Generate candidate repairs: each repair is a set of assertion changes (retract, correct, or time-index) that eliminates all violations. Rank repairs by minimality (fewest changes), breaking ties with provenance priority (prefer changing assertions from lower-reliability sources) and then by recency (prefer keeping newer verified assertions). Apply the winning repair as a transaction: all changes together with the violated constraints, the candidates considered, and the ranking reasons — because a repair is itself a claim that must be auditable. Re-run violation detection after the repair to confirm the graph is clean.", "key_points": ["Constraints are the law: encode them before detecting violations.", "Minimal repair: change as little as possible to restore consistency.", "Tie-break: provenance priority — change the least reliable assertions first.", "Repairs are transactions with full audit: constraints, candidates, reasons."], "requirements": "Machine-checkable constraint set; assertion provenance scores; a repair-ranking policy.", "standards": "No silent repairs. Every repair transaction archived with candidates and reasons.", "citations": ["Database repair / consistent query answering literature (public reference)", "Knowledge graph refinement surveys (public reference)"]}}, {"topic": "Argumentation Frameworks for Conflicts", "cat": "resolution-procedures", "rank": 5, "tier": "Advanced", "name": "argumentation-frameworks", "desc": "Argumentation frameworks turn a conflict into a formal debate: claims become arguments, conflicts become attacks between arguments, and resolution becomes computing which arguments survive. This record introduces Dung-style abstract argumentation — arguments, attack relations, and acceptability semantics (grounded, preferred, stable) — as a rigorous way to adjudicate multi-claim conflicts where attacks chain (A attacks B, B attacks C, so A defends C). It is the formal backbone behind \"the enemy of my enemy\" reasoning in evidence disputes.", "body": {"how_it_works": "Model each claim and each piece of supporting or undermining evidence as an argument node. Draw attack arrows: a retraction attacks the retracted claim, a calibration record attacks an instrument reading, a provenance gap attacks the source's claim. Then compute the acceptable sets under the chosen semantics: the grounded extension (the skeptical core every reasonable position accepts), preferred extensions (maximal defensible positions), and stable extensions (positions attacking everything outside). The grounded extension is the safe output — claims no undefeated attack touches. Where multiple preferred extensions exist, the conflict is genuinely ambiguous and the output is the set of defensible positions with their supporting arguments, not a forced single answer. Argumentation does not replace provenance assessment; it structures it — every attack arrow must be justified by evidence, and unjustified attacks are removed before computation.", "key_points": ["Claims are arguments; conflicts are attacks; resolution is computing survivors.", "Grounded extension = the skeptical core; multiple preferred extensions = genuine ambiguity.", "Attack chains matter: A attacking B defends whatever B attacked.", "Every attack arrow needs evidence — unjustified attacks are removed."], "requirements": "The argument/attack graph; justified attack relations; a chosen acceptability semantics.", "standards": "Attack justifications archived. Ambiguous outputs reported as defensible-position sets.", "citations": ["Dung's abstract argumentation frameworks (1995, public reference)", "Computational argumentation surveys (public reference)"]}}, {"topic": "Version-Controlled Truth", "cat": "temporal-truth", "rank": 5, "tier": "Advanced", "name": "version-controlled-truth", "desc": "Version-controlled truth treats the fact base like source code: every claim is committed with a timestamp, an author, and a parent; corrections are new commits, never edits; and any past state of the truth can be checked out and inspected. This record explains why immutability beats editing (edited history destroys the audit trail), how branching handles genuine disagreement (two defensible positions coexist as branches until evidence merges them), and the merge protocol for bringing branches back together. It is the infrastructure that makes every other procedure in this database auditable.", "body": {"how_it_works": "Store each claim as an immutable record with a hash, timestamp, author, and parent pointer to the claim it supersedes or responds to. Corrections append new records that reference the old ones — the old claim remains readable forever, marked superseded. When two analysts reach different defensible resolutions, each commits to a branch; branches are named, dated, and justified, and the main line continues with the better-supported position. Merging a branch requires the merge protocol: re-run the conflict procedure on the branch's claims against main, produce the merged claim set, and commit the merge with both parents recorded. Any past state is recoverable by checking out the commit — \"what did we believe on March 3rd, and why?\" is always answerable. The discipline that makes it work: no force-pushes, no history rewrites, ever — a rewritten history is indistinguishable from a cover-up.", "key_points": ["Immutability: corrections are new commits, never edits — history is the audit trail.", "Branching holds genuine disagreement: two defensible positions coexist openly.", "Merges re-run the conflict procedure; merge commits record both parents.", "No history rewrites, ever — a rewritten history looks like a cover-up."], "requirements": "Immutable claim storage with hashes; branch/merge protocol; checkout capability for past states.", "standards": "History rewrites prohibited. All supersessions reference their predecessors.", "citations": ["Version control concepts applied to data (public reference)", "Immutable audit log practice (public reference)"]}}, {"topic": "Confidence-Weighted Reconciliation", "cat": "consensus-methods", "rank": 5, "tier": "Advanced", "name": "confidence-weighted-reconciliation", "desc": "Confidence-weighted reconciliation is the capstone consensus method: every claim enters with a confidence score derived from its source reliability, corroboration, and method quality, and the resolution is the confidence-weighted synthesis with the dissent preserved. This record gives the full method — confidence calibration (so 80% means 80%), the weighted synthesis rule, dissent preservation (minority claims are recorded, not erased), and the confidence report that accompanies every resolution. It is the procedure to use when the stakes are highest and the sources are many.", "body": {"how_it_works": "Calibrate confidences first: each source's historical accuracy on this fact class becomes its base confidence, adjusted by the specific claim's corroboration and method quality — and calibration is checked against track records, because uncalibrated confidence is decoration. Combine with the weighted synthesis: for categorical claims, the confidence-weighted vote with the margin reported; for numerical claims, the confidence-weighted mean with the weighted spread as the uncertainty band. Preserve dissent explicitly: minority claims are recorded with their confidence and reasons in the resolution record, because today's dissent is sometimes tomorrow's correction and because erasing it destroys the audit trail. Produce the confidence report: the winning claim, its combined confidence, the margin over the runner-up, the dissent summary, and the calibration basis. When the margin is thin or confidences are low across the board, the method's honest output is a qualified leaning with the uncertainty front and center.", "key_points": ["Calibrate confidences against track records — uncalibrated confidence is decoration.", "Weighted synthesis with margins reported; numerical claims get uncertainty bands.", "Dissent is preserved with reasons — erasing it destroys the audit trail.", "Thin margins produce qualified leanings, not verdicts."], "requirements": "Source track records for calibration; the synthesis rules; a dissent-preservation format; the confidence report template.", "standards": "Confidences must cite their calibration basis. Dissent preservation mandatory.", "citations": ["Forecast calibration literature (public reference)", "Ensemble methods / weighted voting (public reference)"]}}, {"topic": "Contradiction Logging and Audit Trails", "cat": "resolution-procedures", "rank": 5, "tier": "Advanced", "name": "contradiction-audit-trails", "desc": "Every contradiction encountered — resolved or not — is logged with its claims, sources, procedure, and outcome, forming an audit trail that makes the whole conflict-resolution system accountable. This record specifies the contradiction log schema, the audit-trail requirements (who decided, when, on what evidence, with what margin), and the review cycle: periodic audits of the log catch systematic biases, such as one source always winning or one analyst's resolutions always favoring recency. The log is also the training data for improving every procedure in this database.", "body": {"how_it_works": "Log each contradiction at detection time with the conflict brief (claims, sources, type); update the entry as it moves through the pipeline with the procedure used at each step; close it with the resolution, the margin, the dissent, and the decider's identity. The audit trail for a resolution must answer five questions: what was decided, who decided it, when, on what evidence, and by what margin — any resolution that cannot answer all five is incomplete. Run the review cycle quarterly: aggregate the log and look for patterns — win-rate by source (a source winning 100% is a red flag for bias or capture), resolution time by conflict type, reversal rate on re-examination. Feed the findings back: systematic patterns trigger procedure reviews, and the log's resolved cases become the calibration set for confidence scoring. The log is append-only; corrections to log entries are new entries referencing the old.", "key_points": ["Log at detection, update through the pipeline, close with the full resolution.", "The audit trail answers: what, who, when, on what evidence, by what margin.", "Quarterly pattern review catches bias: 100% win rates are red flags.", "The log is append-only and doubles as calibration training data."], "requirements": "The contradiction log schema; the five-question audit standard; a quarterly review schedule.", "standards": "Append-only log. Resolutions missing any of the five audit answers are incomplete.", "citations": ["Audit trail requirements in quality management (ISO 9001, public reference)", "Decision logging in high-reliability organizations (public reference)"]}}, {"topic": "Fallback: When Resolution Is Impossible", "cat": "resolution-procedures", "rank": 5, "tier": "Advanced", "name": "resolution-impossible", "desc": "Sometimes resolution is impossible: the evidence is symmetric, the sources are equally reliable, the key record is lost, or the question is genuinely undecidable with available means. The honest output is not a guess — it is a structured abstention. This record defines the impossibility criteria, the abstention protocol (what is reported instead of an answer), and the re-open triggers (what future evidence would change the verdict). Knowing when to stop is a resolution skill; forced answers in impossible cases are how confident falsehoods are born.", "body": {"how_it_works": "Test the impossibility criteria: evidence symmetry (weighted support within the close-tally band after full provenance work), source parity (top sources score within the noise margin of each other), missing keystone (the one record that would decide is lost or inaccessible), or undecidability (the question cannot be settled even in principle with available methods). If any criterion is met after the full pipeline has run — impossibility is a conclusion, not a shortcut — issue the structured abstention: state the competing claims with their weighted support, state exactly why resolution failed (which criterion), list what is known and what is missing, and define the re-open triggers (\"if the 2019 survey is found, re-run step 4\"). File the abstention in the contradiction log like any resolution; an abstention is a first-class output, reviewed and improvable. The standing rule: a forced answer where abstention was warranted is recorded as a procedure failure.", "key_points": ["Impossibility criteria: symmetry, parity, missing keystone, undecidability.", "Impossibility is a conclusion after the full pipeline — never a shortcut.", "Structured abstention: claims, support, why-failed, known/unknown, re-open triggers.", "Forced answers in impossible cases are procedure failures."], "requirements": "The impossibility criteria checklist; the abstention report format; re-open trigger definitions.", "standards": "Abstentions are first-class logged outputs. Forced answers where abstention was warranted = failure.", "citations": ["Abstention in decision theory (public reference)", "Unknown-unknown handling in risk analysis (public reference)"]}}];
function demoFor(e){
  var L=['RECORD: '+DBTITLE+': '+e.topic,'ID: '+PREFIX+'(seed)','CATEGORY: '+e.cat+' | LADDER: '+e.rank+' ('+e.tier+')','HOW IT WORKS: '+e.body.how_it_works,'KEY POINTS:'];
  e.body.key_points.forEach(function(k,i){L.push('  '+(i+1)+'. '+k);});
  L.push('REQUIREMENTS: '+e.body.requirements);
  L.push('STANDARDS: '+e.body.standards);
  L.push('CITATIONS: '+e.body.citations.join(' | '));
  return 'console.log('+JSON.stringify(L.join('\n'))+');';
}
function generate(seed,opts){
  opts=opts||{};
  var n=DATA.length;
  var e=DATA[(seed-1)%n];
  if(opts.category&&e.cat!==opts.category){ for(var i=0;i<n;i++){ var c=DATA[(seed-1+i)%n]; if(c.cat===opts.category){ e=c; break; } } }
  var cycle=Math.floor((seed-1)/n);
  var rec={
    id:PREFIX+String(seed).padStart(6,'0'),
    name:e.name,
    title:DBTITLE+': '+e.topic+(cycle>0?' (variant '+cycle+')':''),
    description:e.desc,
    category:e.cat,
    ladder:e.rank,
    ladder_rank:e.rank,
    ladder_tier:e.tier,
    src:SRC,
    src_detail:SRC_DETAIL,
    seed:seed,
    how_it_works:e.body.how_it_works,
    key_points:e.body.key_points.slice(),
    requirements:e.body.requirements,
    standards:e.body.standards,
    citations:e.body.citations.slice(),
    demo:{program:demoFor(e)}
  };
  return rec;
}
function escRx(s){return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}
function validate(r){
  var errs=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  if(!new RegExp('^'+escRx(PREFIX)+'\\d{6}$').test(r.id||''))errs.push('id');
  if(typeof r.title!=='string'||r.title.indexOf(DBTITLE)!==0)errs.push('title');
  if(CATS.indexOf(r.category)<0)errs.push('category');
  if(!(r.ladder>=1&&r.ladder<=5))errs.push('ladder');
  if(r.src!==SRC)errs.push('src');
  if(typeof r.description!=='string'||r.description.length<200)errs.push('description<200');
  REQUIRED.forEach(function(k){if(r[k]===undefined||r[k]===null)errs.push('missing:'+k);});
  if(!Array.isArray(r.key_points)||!r.key_points.length)errs.push('key_points');
  if(!Array.isArray(r.citations)||!r.citations.length)errs.push('citations');
  if(!r.demo||typeof r.demo.program!=='string'||!r.demo.program.length)errs.push('demo');
  if(/lorem ipsum/i.test(JSON.stringify(r)))errs.push('placeholder');
  return {ok:errs.length===0,errors:errs};
}
function driftCheck(rec,sample){
  var dups=(sample||[]).filter(function(x){return x&&x.title===rec.title&&x.category===rec.category;});
  return dups.length?{ok:false,errors:['duplicate title+category already in archive']}:{ok:true,errors:[]};
}
var api={generate:generate,validate:validate,driftCheck:driftCheck,slug:'fact-conflict-contradiction-resolution',version:'jahdb-fact-conflict-contradiction-resolution-1.0'};
if(typeof module!=='undefined'&&module.exports)module.exports=api;
if(typeof window!=='undefined'){
  window["jahdb_fact_conflict_contradiction_resolution"]=api;
  try{if(window.JAHDB&&JAHDB.registerGenerator)JAHDB.registerGenerator('fact-conflict-contradiction-resolution',api);}catch(e){}
}
})();
